/**
 * Note: When using the Node.JS APIs, the config file
 * doesn't apply. Instead, pass options directly to the APIs.
 *
 * All configuration options: https://remotion.dev/docs/config
 */

import { Config } from "@remotion/cli/config";

Config.setRspack(true);
Config.setVideoImageFormat("jpeg");
Config.setJpegQuality(92);
Config.setOverwriteOutput(true);
// Footage is regenerated by scripts/capture.mjs and never committed, so the
// public dir IS the capture output.
Config.setPublicDir("capture/public");
// H.264 + yuv420p for LinkedIn/Instagram/PowerPoint playback. Skipped for
// audio-only renders (AUDIO_ONLY=1 ... --codec=wav), which reject --crf.
if (process.env.AUDIO_ONLY !== "1") {
  Config.setCodec("h264");
  Config.setPixelFormat("yuv420p");
  Config.setCrf(20);
}
